import sys
from collections import deque

class QuadNode:
    __slots__ = ('val', 'isLeaf', 'children')
    def __init__(self, val=0, isLeaf=False, children=None):
        self.val = val
        self.isLeaf = isLeaf
        self.children = children if children is not None else [None] * 4

def serialize(root):
    res = []
    q = deque([root])
    while q:
        node = q.popleft()
        res.append('%d %d' % (node.val, 1 if node.isLeaf else 0))
        if not node.isLeaf:
            q.extend(node.children)
    return res

def build(grid, r, c, size):
    first = grid[r][c]
    same = True
    for i in range(r, r + size):
        for j in range(c, c + size):
            if grid[i][j] != first:
                same = False
                break
        if not same:
            break
    if same:
        return QuadNode(first, True)
    half = size // 2
    children = [
        build(grid, r, c, half),
        build(grid, r, c + half, half),
        build(grid, r + half, c, half),
        build(grid, r + half, c + half, half),
    ]
    return QuadNode(0, False, children)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    root = build(grid, 0, 0, m)
    for line in serialize(root):
        print(line)

