import sys
from collections import deque

class QuadNode:
    __slots__ = ('val', 'isLeaf', 'children')
    def __init__(self, val=0, isLeaf=False, children=None):
        self.val = val
        self.isLeaf = isLeaf
        self.children = children if children is not None else [None] * 4

def serialize(root):
    res = []
    q = deque([root])
    while q:
        node = q.popleft()
        res.append('%d %d' % (node.val, 1 if node.isLeaf else 0))
        if not node.isLeaf:
            q.extend(node.children)
    return res

def build(grid, r, c, size, ps):
    total = ps[r + size][c + size] - ps[r][c + size] - ps[r + size][c] + ps[r][c]
    if total == 0 or total == size * size:
        return QuadNode(1 if total else 0, True)
    half = size // 2
    children = [
        build(grid, r, c, half, ps),
        build(grid, r, c + half, half, ps),
        build(grid, r + half, c, half, ps),
        build(grid, r + half, c + half, half, ps),
    ]
    return QuadNode(0, False, children)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    ps = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        row_sum = 0
        for j in range(n):
            row_sum += grid[i][j]
            ps[i + 1][j + 1] = ps[i][j + 1] + row_sum
    root = build(grid, 0, 0, m, ps)
    for line in serialize(root):
        print(line)
